[96984] = {"El corazón de la perturbación", {"Recupera la mota Arcana en la Ciudad de Dalaran para el magus Wordeen Vacuamirada, en Molino Tarren."}},
[96986] = {"El Caballero de la Tumba", {"Derrota a Atrexis el Caballero de la Tumba en la Ciudad de Dalaran. Después, informa a Melisara en Molino Tarren."}},
[96987] = {"Educación oportunista", {"Consigue La fundación de Dalaran en la Ciudad de Dalaran para Rexxie Aferracobre, en la entrada a las cloacas."}},
[96988] = {"Fuente de poder", {"Consigue 6 núcleos de centinela agrietados en la Ciudad de Dalaran para el doctor Martin Felben de Entrañas."}},
[97003] = {"Chol'aruk el Devorador", {"Lleva la cabeza de Chol'aruk a Gur'ak en Los Baldíos."}},
[97005] = {"Chol'aruk el Devorador", {"Lleva la cabeza de Chol'aruk a Bainham en Los Baldíos."}},
[97047] = {"Cocinero entre rejas", {"Busca en la Base de Kurzen la llave que abre la jaula de Wendel y un disfraz con el que pueda salir sin levantar sospechas."}},
[97048] = {"Vuelta al puerto", {"Habla con la capitana Aransas en Bahía del Botín."}},
[97130] = {"Antiguos secretos Gurubashi", {"Recupera un antiguo ídolo Gurubashi en la Ciudad Sumergida."}},
[97196] = {"El ojo del Gélido", {"Recupera el ojo del Gélido en la Zahúrda Rajacieno."}},
[97220] = {"El favor de Philmor", {"Lleva el envío a la torre de entrada a la entrada del almacén ubicada en la tienda Queso de Trias, en el Distrito de Mercaderes."}},
[97222] = {"Bienes de la torre de entrada", {"Lleva el envío a la torre de entrada en el piso de arriba de la tienda Queso de Trias y déjalo en la puerta."}},
[97223] = {"Matriarca Garrasangre", {"Llévale los huevos de la matriarca Garrasangre a Xar'Ti, en el Poblado Sen'jin."}},
[97225] = {"Ídolos loa olvidados", {"Reúne 8 ídolos loa olvidados en las Islas del Eco. Llévaselos a maese Gadrin al Poblado Sen'jin."}},
[97234] = {"Sala de lectura", {"Lleva el material de lectura envuelto a la biblioteca de Ventormenta."}},
[97236] = {"Colmillo de Githyiss", {"Entrega el colmillo de Githyiss a alguien que esté interesado en el estudio de las arañas en Aldrassil."}},
[97237] = {"Estanterías a tu disposición", {"Encuentra todos los materiales de lectura que se encuentran por la biblioteca y vuelve con Roy Lewells en el Parque de Ventormenta."}},
[97242] = {"El popurrí de Yelmak", {"Recoge algunos esquejes de las apiáceas y de las eneas que crecen alrededor del estanque del Valle del Honor y entrégaselos a Kor'geld en la tienda de Alquimia y pociones de Yelmak."}},
[97243] = {"La llamada del fuego", {"Llévale la antorcha de la llama latente a Olariaan Ardeveloz en el santuario de las llamas que está en las Tierras Bajas de los Soplabayas."}},
[97244] = {"La llamada del fuego", {"Asesina al sacerdote del cielo Faladiel en las Tierras Bajas de los Soplabayas y consigue su corazón."}},
[97245] = {"La llamada del fuego", {"Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota a este espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Ardeveloz en las Tierras Bajas de los Soplabayas una vez que te alces con la victoria."}},
[97246] = {"A plato puesto", {"Visita la Fosa de lava de Borstan y dile que Thatog quiere que le entregues personalmente el almuerzo de Migi."}},
[97249] = {"Comida favorita", {"Llévale el almuerzo a Migi detrás del Fuerte Grommash."}},
[97250] = {"Culpa incorrecta, corregida", {"Mata a los soldados de la Alianza que han invadido Los Baldíos en la frontera con el Marjal Revolcafango y luego vuelve con el bruto Logmar en el Campamento Taurajo."}},
[97253] = {"Volver con piezas de una pieza", {"Consigue 5 puñados de piezas complicadas del campamento pirata superior que hay al sur de Trinquete y luego vuelve con Desdio el Desdichado en Trinquete."}},
[97257] = {"La llamada del fuego", {"Espera a que Olariaan empiece el ritual en el blandón de ofrendas y sigue sus instrucciones.","","Debes entregar la Llama eterna en Valanaar antes de que se agote el tiempo."}},
[97263] = {"Ha llegado tu paquete", {"Entrega a Eldrun su paquete perdido."}},
[97265] = {"Odio al Odio Feroz", {"Derrota a sátiros Odio Feroz en Sargeron, Desolace, y luego vuelve con Aka'rai en la Aldea Cazasombras."}},
[97275] = {"Elaboración a fuego lento", {"Dale la poción de Yelmak a Whuut."}},
[97277] = {"Grund y Gozwin", {"Busca el campamento de Grund y Gozwin en las colinas que hay al noroeste. Recupera el registro de mecánico de Gozwin y mata al leopardo de la nieve merodeador."}},
[97279] = {"Armas extraviadas", {"Recoge 6 armas de entrenamiento abandonadas y llévaselas a Kzan Trallafusta en El Cubil."}},
[97281] = {"Una tormenta inminente", {"Llévale el orbe de tormenta sin brillo a Rezlak, cerca del Barranco Árido."}},
[97282] = {"Potencial tormentoso", {"Llévale 5 órganos de truenagarto cargados a Rezlak, cerca del Barranco Árido."}},
[97286] = {"Acceso a la investigación", nil},
[97287] = {"Negociaciones astutas", {"Habla con la imagen de la archimaga Modera cerca de Dalaran."}},
[97288] = {"Tormento interminable", {"Entrega la cabeza abominable al maestro boticario Faranell en Entrañas."}},
[97289] = {"Tormento interminable", {"Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas."}},
[97290] = {"Tormento interminable", {"Informa de tus hallazgos al maestro boticario Faranell de Entrañas."}},
[97291] = {"Tormento interminable", {"Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas."}},
[97292] = {"Tormento interminable", {"Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell."}},
[97326] = {"Descanso rocoso", {"Llévale 8 rocas suaves a Thra detrás del Fuerte Grommash."}},
[97328] = {"Cualquier objeto de valor", {"Recupera 8 envíos robados de las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévaselos a alguien en Bahía del Botín."}},
[97485] = {"Tradiciones de la cima", {"Compra un fardo de hierbas a Nida la herborista, un fardo de ramas de cedro a Nata la proveedora de encantamientos, hilo tendinoso a Mahu el proveedor de suministros de peletería, y sílex y yesca ceremoniales a Naal el proveedor de artículos de cocina.","","Combina los objetos y esparce el incienso desde el Alto de los Cazadores."}},
[97538] = {"Pigmentos para pinturas", {"Tah Pezuña Invernal en Cima del Trueno quiere 30 vainas de hierbaoscura del Lago Mirkfallon."}},
[97539] = {"Suturas sedosas", {"Entrega 12 sedas de araña quirúrgicas al doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi."}},
[97558] = {"Pieles para los Renegados", {"Lleva 8 membranas de ala de murciumbrío, 6 pellejos de can oscuro y 3 piel de múrloc Anca Vil a Shelene Rhobart."}},
[97583] = {"CONTONEOS.", {"Compra fango de babosa nutritivo y vuelve con tu inquieta y amistosa babosa. Si parece cansada, baila con ella de nuevo para llamar su atención."}},
[97663] = {"Suministros y estudios", nil},
[97891] = {"Veloz corredor de pociones", {"Llévale una poción inestable al doctor Martin Felben en El Apothecarium antes de que se acabe el tiempo."}},
[97894] = {"Asuntos en Auberdine", {"Comprueba cómo está Gorbold Mano de Acero en Auberdine, en Costa Oscura.","","Borgus ha mencionado que puedes coger un barco en el muelle más al sur del Puerto de Ventormenta."}},
